// Flow 2 · test link url: builds the links from the signed values.
const BASE = 'https://YOUR_N8N_HOST';
const { fid, exp, sig } = $input.first().json;
const qs = `fid=${encodeURIComponent(fid)}&exp=${exp}&sig=${sig}`;
return [{ json: {
  test_url: `${BASE}/form-test/decide?${qs}`,
  prod_url: `${BASE}/form/decide?${qs}`,
  expires_at: new Date(exp * 1000).toISOString(),
} }];

// Flow 2 · test link input (manual helper, not part of the form path)
// Put the id of an open finding below and run this branch with "Execute workflow"
// from the "Mint test link" trigger. The signature is made inside n8n with the same
// credential, so the HMAC key never leaves n8n.

const FINDING_ID = 'PUT_A_FINDING_ID_HERE';
const TTL_DAYS = 3;

const exp = Math.floor(Date.now() / 1000) + TTL_DAYS * 24 * 3600;
return [{ json: { fid: FINDING_ID, exp } }];

// Flow 2 · check decision (Run Once for All Items)
// Runs after the decision page is submitted. Checks again that the link has not expired
// and the finding is still open (it may have been decided in another tab), validates
// the answers and builds the rows for decisions_log and findings.

const DISPOSITIONS = ['accepted', 'false_positive', 'suppressed', 'needs_evidence', 'escalated'];
const CLOSING = ['accepted', 'false_positive', 'suppressed']; // these take the finding out of the emails
const SEVERITIES = ['critical', 'high', 'medium', 'low', 'info'];

const link = $('check signature').first().json;
const answers = $('Form: decision').first().json;
const row = $input.first().json ?? {};
const now = new Date();

const clean = (v, n) => String(v ?? '')
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
  .trim()
  .slice(0, n);

const disposition = clean(answers['Disposition'], 40);
const finalSeverity = clean(answers['Final severity'], 20);
const reason = clean(answers['Reason'], 1000);
const reviewer = clean(answers['Reviewer'], 120);

let problem = null;
if (link.exp * 1000 <= now.getTime()) problem = 'expired';
else if (String(row.id ?? '') !== link.fid) problem = 'not found';
else if (String(row.status ?? '') === 'decided') problem = 'already decided';
else if (!DISPOSITIONS.includes(disposition)) problem = 'bad disposition';
else if (!SEVERITIES.includes(finalSeverity)) problem = 'bad severity';
else if (!reason) problem = 'missing reason';
else if (!reviewer) problem = 'missing reviewer';

if (problem) return [{ json: { ok: false, problem, fid: link.fid } }];

const decidedAt = now.toISOString().replace(/\.\d{3}Z$/, 'Z');
const firstSeen = Date.parse(row.first_seen_at);
const hours = Number.isFinite(firstSeen) ? Math.round(((now.getTime() - firstSeen) / 36e5) * 100) / 100 : '';
const newStatus = CLOSING.includes(disposition) ? 'decided' : 'candidate';

return [{ json: {
  ok: true,
  fid: link.fid,
  disposition,
  log: {
    logged_at: decidedAt,
    finding_id: link.fid,
    pr: row.last_pr ?? '',
    previous_status: row.status ?? '',
    new_status: newStatus,
    disposition,
    final_severity: finalSeverity,
    reason,
    reviewer,
    source: 'form',
  },
  update: {
    id: link.fid,
    status: newStatus,
    disposition,
    final_severity: finalSeverity,
    reason,
    reviewer,
    decided_at: decidedAt,
    time_to_decision_h: hours,
  },
} }];

