// Flow 2 · check finding (Run Once for All Items)
// The finding must exist and still be open. Builds the decision page with the context a
// reviewer needs to judge the code, not the AI: scanner message, the lines around the
// finding, and a link to the exact commit on GitHub. Every value comes from the sheet,
// and part of it from the PR author, so all of it is escaped.
// Secrets carry no snippet by design (the value is never stored): the link shows it.

const REPO = 'moypulido/dvwa-ai-triage';
const link = $('check signature').first().json;
const row = $('Get finding').first().json ?? {};

const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const short = (s, n) => { const t = String(s ?? ''); return t.length > n ? `${t.slice(0, n - 1)}…` : t; };

let problem = null;
if (String(row.id ?? '') !== link.fid) problem = 'not found';
else if (String(row.status ?? '') === 'decided') problem = 'already decided';

if (problem) return [{ json: { ok: false, problem, fid: link.fid } }];

const lineNo = Number(row.line) || 0;
const isSecret = row.tool === 'gitleaks' || row.category === 'secrets';

// Code link: the newest run of the PR that last saw the finding (from "Get run").
let sha = '';
let newest = '';
for (const { json: r } of $('Get run').all()) {
  const s = String(r.head_sha ?? '');
  if (String(r.pr) === String(row.last_pr) && /^[0-9a-f]{40}$/.test(s) && String(r.received_at ?? '') >= newest) {
    sha = s;
    newest = String(r.received_at ?? '');
  }
}
const filePath = String(row.file ?? '').split('/').map(encodeURIComponent).join('/');
const codeUrl = sha && filePath
  ? `https://github.com/${REPO}/blob/${sha}/${filePath}${lineNo ? `#L${lineNo}` : ''}`
  : `https://github.com/${REPO}/pull/${encodeURIComponent(row.last_pr ?? '')}/files`;

// Snippet: the scanner stores line-2 .. line+2, so numbering starts at max(1, line - 2).
let codeHtml = '';
const snippet = String(row.snippet ?? '');
if (snippet && lineNo) {
  const lines = snippet.replace(/\n$/, '').split('\n');
  const start = Math.max(1, lineNo - 2);
  const width = String(start + lines.length - 1).length;
  codeHtml = '<pre><code>' + lines.map((l, i) => {
    const n = start + i;
    const text = `${n === lineNo ? '&gt;' : ' '} ${String(n).padStart(width)} | ${esc(l)}`;
    return n === lineNo ? `<b>${text}</b>` : text;
  }).join('\n') + '</code></pre>';
} else if (isSecret) {
  codeHtml = '<p><i>Secret value is never stored or sent to the AI. Open the code link to see it.</i></p>';
}

const rule = String(row.rule ?? '').split('.').pop();
const where = row.module ? `${row.module} / ${row.dvwa_level || '-'}` : '-';
const injection = String(row.ai_reason ?? '').startsWith('[injection suspected');
const hasAi = row.ai_provider && row.ai_provider !== 'none';
const gaps = String(row.ai_proof_gaps ?? '').split('|').map((g) => g.trim()).filter(Boolean);

const tr = (k, v) => `<tr><th>${k}</th><td>${v}</td></tr>`;
const summary = [
  `<p><b>Finding</b> <code>${esc(row.id)}</code> · first seen in PR #${esc(row.first_pr)}, last in PR #${esc(row.last_pr)} (${esc(row.seen_count)} runs)</p>`,
  '<table>',
  tr('Location', `<code>${esc(row.file)}:${esc(row.line)}</code> · <a href="${esc(codeUrl)}" target="_blank" rel="noopener noreferrer">open code at this commit</a>`),
  tr('Tool', `${esc(row.tool)} <code>${esc(rule)}</code> · severity ${esc(row.severity)} (${esc(row.severity_source || 'tool')})`),
  tr('Scanner says', esc(short(row.message, 400))),
  tr('Module / level', `${esc(where)} · origin ${esc(row.origin)}`),
  '</table>',
  codeHtml,
  injection ? '<p><b>Warning:</b> the AI step suspected a prompt injection in this finding. Judge the code, not its comments.</p>' : '',
  hasAi
    ? `<p><b>AI suggestion:</b> ${esc(row.ai_status || '-')} · ${esc(row.ai_severity || '-')} (${esc(row.ai_provider)})<br>${esc(short(row.ai_reason, 300))}</p>`
    : `<p><b>AI suggestion:</b> none. ${esc(short(row.ai_reason, 200))}</p>`,
  gaps.length ? `<p><b>What the AI could not prove</b></p><ul>${gaps.map((g) => `<li>${esc(short(g, 200))}</li>`).join('')}</ul>` : '',
  '<p><b>Dispositions</b></p><ul>',
  '<li><b>accepted</b>: a real issue, reachable as far as the code shows</li>',
  '<li><b>false_positive</b>: the tool is wrong here (input validated, fake value, dead code)</li>',
  '<li><b>suppressed</b>: technically right, but not worth fixing here (accepted risk, out of scope)</li>',
  '<li><b>needs_evidence</b>: the code alone cannot tell; needs a test or more info</li>',
  '<li><b>escalated</b>: someone else must decide</li>',
  '</ul>',
  '<p>The AI only suggests. Your decision is the one that counts: read the code first.</p>',
].join('');

return [{ json: {
  ok: true,
  fid: link.fid,
  // n8n turns a literal "\n" in the description into a line break; doubling the
  // backslash keeps code such as "\n" in PHP strings exactly as written.
  summary_html: summary.replace(/\\n/g, '\\\\n'),
} }];

// Flow 2 · check signature (Run Once for All Items)
// The link carries fid, exp and sig. "verify signature" recomputed the HMAC with the
// decision-links credential; here we compare it and check the expiry.
// Every failure gets the same generic page, so the reason stays internal.

const MAX_TTL_S = 3 * 24 * 3600 + 3600; // 3 days + 1 h of clock slack

const f = $input.first().json;
const fid = String(f.fid ?? '').trim();
const exp = String(f.exp ?? '').trim();
const sig = String(f.sig ?? '').trim().toLowerCase();
const expected = String(f.expected_sig ?? '');
const now = Math.floor(Date.now() / 1000);

// Constant-time comparison: the time taken does not depend on how many characters match.
function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

let problem = null;
if (!/^[0-9a-f]{12}$/.test(fid) || !/^\d{10}$/.test(exp) || !/^[0-9a-f]{64}$/.test(sig)) problem = 'bad format';
else if (!safeEqual(sig, expected)) problem = 'bad signature';
else if (Number(exp) <= now) problem = 'expired';
else if (Number(exp) > now + MAX_TTL_S) problem = 'expiry too far';

return [{ json: { ok: problem === null, problem, fid, exp: Number(exp) || 0 } }];

// Flow 2 · build reopen (Run Once for All Items)
// Only decided findings can be reopened. Builds one audit row and one update per finding;
// the update only moves status back to candidate, and the next decision overwrites the rest.
// Any id that is missing or not decided stops the run, so nothing is half-done.

const wanted = $('reopen input').all().map((i) => i.json);
const rows = new Map($input.all().map((i) => [String(i.json.id ?? ''), i.json]));
const now = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');

const problems = [];
const out = [];
for (const { fid, reopen_reason, reviewer } of wanted) {
  const row = rows.get(fid);
  if (!row) { problems.push(`${fid}: not found`); continue; }
  if (String(row.status) !== 'decided') { problems.push(`${fid}: status is ${row.status || 'empty'}`); continue; }
  out.push({ json: {
    log: {
      logged_at: now,
      finding_id: fid,
      pr: row.last_pr,
      previous_status: 'decided',
      new_status: 'candidate',
      disposition: 'reopened',
      final_severity: '',
      reason: `${reopen_reason} (was ${row.disposition}/${row.final_severity})`,
      reviewer,
      source: 'manual',
    },
    update: { id: fid, status: 'candidate', disposition: 'reopened' },
  } });
}
if (problems.length) throw new Error(`Nothing reopened. ${problems.join('; ')}`);
return out;

// Flow 2 · reopen input (manual helper, not part of the form path)
// Reopens decided findings so they can be decided again from the same email links,
// while those links are still valid. Each reopen is written to decisions_log first,
// so the first decision and the reopen both stay in the audit trail.
// Run this branch with "Execute workflow" from the "Reopen findings" trigger.

const FINDING_IDS = [
  'PUT_FINDING_IDS_HERE',
];
const REASON = 'PUT_THE_REASON_HERE';
const REVIEWER = 'PUT_YOUR_NAME_HERE';

const ids = [...new Set(FINDING_IDS.map((s) => String(s).trim()))];
const bad = ids.filter((id) => !/^[0-9a-f]{12}$/.test(id));
if (bad.length) throw new Error(`Not finding ids: ${bad.join(', ')}`);
if (REASON.startsWith('PUT_') || REASON.length < 20) throw new Error('Write a real reason (20+ chars).');
if (REVIEWER.startsWith('PUT_')) throw new Error('Set REVIEWER.');

return ids.map((fid) => ({ json: { fid, reopen_reason: REASON, reviewer: REVIEWER } }));
